  if (emotion === 'JOY') return JOY_VARIANTS[typeof intensity === 'number' ? intensity : 7] || JOY_VARIANTS[7];
  if (emotion === 'TRUST') return TRUST_VARIANTS[typeof intensity === 'number' ? intensity : 3] || TRUST_VARIANTS[3];
  if (emotion === 'FEAR') return FEAR_VARIANTS[typeof intensity === 'number' ? intensity : 12] || FEAR_VARIANTS[12];
  if (emotion === 'SURPRISE') return SURPRISE_VARIANTS[typeof intensity === 'number' ? intensity : 6] || SURPRISE_VARIANTS[6];
  if (emotion === 'SADNESS') return SADNESS_VARIANTS[typeof intensity === 'number' ? intensity : 5] || SADNESS_VARIANTS[5];
  if (emotion === 'DISGUST') return DISGUST_VARIANTS[typeof intensity === 'number' ? intensity : 8] || DISGUST_VARIANTS[8];
  if (emotion === 'ANGER') return ANGER_VARIANTS[typeof intensity === 'number' ? intensity : 12] || ANGER_VARIANTS[12];
  if (emotion === 'ANTICIPATION') return ANTICIPATION_VARIANTS[typeof intensity === 'number' ? intensity : 6] || ANTICIPATION_VARIANTS[6];
  if (emotion === 'SPECIAL_1') return DRUNK_VARIANTS[typeof intensity === 'number' ? intensity : 2] || DRUNK_VARIANTS[2];
  if (emotion === 'SPECIAL_2') return WOUNDED_VARIANTS[typeof intensity === 'number' ? intensity : 2] || WOUNDED_VARIANTS[2];
  const meta = EMOTION_META[emotion];
  return meta.tiers[intensity as string] || meta.tiers['MAX'];
};

