      let finalMime = mediaItem.mimeType;
      if (autoRemoveBg) {
        try { finalBase64 = await removeBackground(mediaItem.base64, mediaItem.mimeType); finalMime = 'image/png'; } catch (e) { console.error(e); }
      }
      setReferences([{ mediaId: mediaItem.mediaId, base64: finalBase64, mimeType: finalMime }]);
      setIsProcessingRefs(false);
    } catch (e) { setIsProcessingRefs(false); }
  };

  const generateSprite = async (emotion: Emotion) => {
    const slot = slots.find(s => s.emotion === emotion);
    if (!slot || (emotion !== 'NEUTRAL' && references.length === 0) || cancelBatchRef.current) return;
    setSlots(prev => prev.map(s => s.emotion === emotion ? { ...s, status: 'generating', error: undefined } : s));
    try {
      const tierInfo = getTierInfo(emotion, slot.intensity);
      const basePrompt = mode === 'FULLBODY' ? 'High quality full body character sprite, isolated on solid background' : 'High quality character portrait sprite, head and shoulders, isolated on solid background';
      const result = await Flow.generate.image({
        prompt: `${basePrompt}, ${characterName}. Facial expression: ${tierInfo.prompt}. ${description}`,
        referenceImageMediaIds: references.map(r => r.mediaId),
        modelDisplayName: '🍌 Nano Banana Pro',
        aspectRatio: mode === 'FULLBODY' ? '3:4' : '1:1'
      });
      if (cancelBatchRef.current) {
        setSlots(prev => prev.map(s => s.emotion === emotion ? { ...s, status: 'idle' } : s));
        return;
      }
      let finalBase64 = result.base64;
      let finalMediaId = result.mediaId;
      if (autoRemoveBg) {
        setSlots(prev => prev.map(s => s.emotion === emotion ? { ...s, status: 'processing' } : s));
        finalBase64 = await removeBackground(result.base64, result.mimeType);
        const saved = await Flow.save({ base64: finalBase64, mimeType: 'image/png', name: getFilename(emotion, slot.intensity) });
        finalMediaId = saved.mediaId;
      }
      setSlots(prev => prev.map(s => s.emotion === emotion ? { ...s, status: 'done', base64: finalBase64, mediaId: finalMediaId } : s));
    } catch (e) {
      setSlots(prev => prev.map(s => s.emotion === emotion ? { ...s, status: 'error', error: 'Failed' } : s));
    }
  };

  const handleImportSprite = async (emotion: Emotion) => {
    const slot = slots.find(s => s.emotion === emotion);
    if (!slot) return;
    try {
      const mediaItem = await Flow.media.select({ filter: 'image' });
      setSlots(prev => prev.map(s => s.emotion === emotion ? { ...s, status: 'processing', error: undefined } : s));

      let finalBase64 = mediaItem.base64;
      let finalMediaId = mediaItem.mediaId;

      if (autoRemoveBg) {
        finalBase64 = await removeBackground(mediaItem.base64, mediaItem.mimeType);
        const saved = await Flow.save({ 
          base64: finalBase64, 
          mimeType: 'image/png', 
          name: `${getFilename(emotion, slot.intensity)} - Imported` 
        });
        finalMediaId = saved.mediaId;
      }

      setSlots(prev => prev.map(s => s.emotion === emotion ? { ...s, status: 'done', base64: finalBase64, mediaId: finalMediaId } : s));
    } catch (e) {
      setSlots(prev => prev.map(s => s.emotion === emotion ? { ...s, status: 'error', error: 'Import Failed' } : s));
    }
  };

  const handleBatchGenerate = async () => {
    if (references.length === 0 || isBatchGenerating) return;
    setIsBatchGenerating(true);
    cancelBatchRef.current = false;
    const order = activeTab === 'primary' ? EMOTION_ORDER : SPECIAL_ORDER;
    for (const emotion of order) {
      if (cancelBatchRef.current) break;
      const slot = slots.find(s => s.emotion === emotion);
      // Generate only if slot exists, is not excluded, and is not already done
      if (slot && slot.status !== 'done' && !slot.excluded) await generateSprite(emotion);
    }
    setIsBatchGenerating(false);
  };

  const handleStopBatch = () => {
    cancelBatchRef.current = true;
    setIsBatchGenerating(false);
    // Reset any slots that were currently generating but not finished
    setSlots(prev => prev.map(s => (s.status === 'generating' || s.status === 'processing') ? { ...s, status: 'idle' } : s));
  };

  const handleDownloadAll = async () => {
    const order = activeTab === 'primary' ? EMOTION_ORDER : SPECIAL_ORDER;
    const readySlots = slots.filter(s => 
      order.includes(s.emotion) && // Tab matching
      !s.excluded &&               // Only active slots
      s.status === 'done' && 
      s.base64
    );

    if (readySlots.length === 0) return;
    setDownloadState('zipping');
    try {
      const zip = new JSZip();
      readySlots.forEach(slot => zip.file(`${getFilename(slot.emotion, slot.intensity)}.png`, slot.base64!, { base64: true }));
      const blob = await zip.generateAsync({ type: 'blob' });
      const reader = new FileReader();
      reader.onload = async () => {
        const base64 = (reader.result as string).split(',')[1];
        const tabLabel = activeTab === 'primary' ? 'Standard' : 'Special';
        await Flow.download({ base64, mimeType: 'application/zip', filename: `${characterName || 'Sprite'}_${tabLabel}_Pack.zip` });
        setDownloadState('done'); setTimeout(() => setDownloadState('idle'), 2000);
      };
      reader.readAsDataURL(blob);
    } catch (e) { setDownloadState('idle'); }
  };

  const gridSlots = slots.filter(s => (activeTab === 'primary' ? EMOTION_ORDER : SPECIAL_ORDER).includes(s.emotion));
  const activeCount = gridSlots.filter(s => !s.excluded).length;

  return (
    <div className="flex h-screen w-screen bg-[#0e0e0e] text-white overflow-hidden">
      {/* Configuration Sidebar */}
      <div className="w-[280px] border-r border-white/10 flex flex-col p-4 gap-4 overflow-y-auto no-scrollbar bg-[#0e0e0e] h-full shrink-0">
        <div className="flex flex-col gap-1.5">
          <SectionLabel>Identification</SectionLabel>
          <input 
            type="text" placeholder="Character Name" value={characterName}
            onChange={(e) => setCharacterName(e.target.value)} disabled={isBatchGenerating}
            className="w-full h-10 bg-[#1a1a1a] border border-[#595959] focus:border-white/40 transition-colors rounded-xl px-4 text-[12px] font-medium outline-none"
          />
        </div>

        <div className="flex flex-col gap-1.5">
          <SectionLabel>Capture Mode</SectionLabel>
          <div className="flex w-full bg-[#1a1a1a] rounded-xl p-1 border border-white/5">
            {[
              { id: 'PORTRAIT', label: 'Portrait', icon: 'account_circle' },
              { id: 'FULLBODY', label: 'Full Body', icon: 'person' }
            ].map(m => (
              <button 
                key={m.id} onClick={() => setMode(m.id as SpriteMode)} disabled={isBatchGenerating}
                className={`flex-1 flex items-center justify-center gap-2 h-9 text-[10px] font-black uppercase tracking-wider rounded-lg transition-all ${mode === m.id ? 'bg-white text-black shadow-lg' : 'text-white/40 hover:text-white/60'}`}
              >
                <span className="material-symbols-outlined text-[16px]">{m.icon}</span>
                {m.label}
              </button>
            ))}
          </div>
        </div>

        <div className="flex flex-col gap-1.5">
          <SectionLabel>Base Design</SectionLabel>
          <div className="flex gap-2">
            <div className="w-24 aspect-square rounded-xl border border-[#595959] overflow-hidden bg-[#111] relative shrink-0 group">
              {references[0] ? (
                <img src={`data:image/png;base64,${references[0].base64}`} className="w-full h-full object-cover" />
              ) : (
                <button onClick={handleAddReferences} disabled={isProcessingRefs} className="w-full h-full flex flex-col items-center justify-center gap-2 hover:bg-white/5 transition-all">
                  <span className="material-symbols-outlined text-[24px] text-white/20 group-hover:text-white/40">add_photo_alternate</span>
                  <span className="text-[8px] font-black text-white/20">Design</span>
                </button>
              )}
              {references[0] && !isBatchGenerating && (
                <button onClick={() => setReferences([])} className="absolute top-1 right-1 w-5 h-5 rounded-full bg-black/60 flex items-center justify-center hover:bg-red-500 transition-all">
                  <span className="material-symbols-outlined text-[14px]">close</span>
                </button>
              )}
            </div>
            <textarea 
              placeholder="Detailed visual cues (outfit, accessories, style)..." value={description} onChange={(e) => setDescription(e.target.value)} disabled={isBatchGenerating}
              className="flex-1 h-24 bg-[#1a1a1a] border border-[#595959] rounded-xl p-3 text-[11px] resize-none outline-none focus:border-white/40 transition-colors"
            />
          </div>
        </div>

        <div className="mt-auto flex flex-col gap-3">
          <div className="flex items-center justify-between bg-[#1a1a1a] border border-white/5 rounded-xl p-3 px-4">
            <div className="flex flex-col">
              <span className="text-[10px] font-black text-white uppercase">Transparency</span>
              <span className="text-[9px] text-white/40">Auto BG Removal</span>
            </div>
            <button onClick={() => !isBatchGenerating && setAutoRemoveBg(!autoRemoveBg)} className={`w-10 h-5 rounded-full relative transition-all ${autoRemoveBg ? 'bg-green-500' : 'bg-white/10'}`}>
              <div className={`absolute top-1 w-3 h-3 rounded-full bg-white transition-all ${autoRemoveBg ? 'left-6' : 'left-1'}`} />
            </button>
          </div>
          <div className="p-4 rounded-xl border border-white/5 bg-white/5 flex flex-col items-center">
            <span className="text-[8px] font-black text-white/20 uppercase tracking-[4px]">Engine Status</span>
            <span className="text-[10px] font-black text-green-500 uppercase mt-1">Banana Pro Ready</span>
          </div>
        </div>
      </div>

      {/* Main Workspace */}
      <div className="flex-1 flex flex-col h-full bg-[#0e0e0e]">
        {/* Tab Header */}
        <div className="shrink-0 flex items-center justify-between h-20 px-8 border-b border-white/5 bg-black/20">
          <div className="flex bg-[#1a1a1a] rounded-2xl p-1 border border-white/5 shadow-2xl">
            {[
              { id: 'primary', label: 'Plutchik Grid' },
              { id: 'special', label: 'Special Emotes' }
            ].map(tab => (
              <button 
                key={tab.id} onClick={() => setActiveTab(tab.id as any)}
                className={`px-6 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${activeTab === tab.id ? 'bg-white text-black shadow-lg' : 'text-white/40 hover:text-white'}`}
              >
                {tab.label}
              </button>
            ))}
          </div>

          <div className="flex items-center gap-3">
            <button onClick={handleReset} className="h-10 px-6 rounded-xl border border-white/10 text-[10px] font-black uppercase tracking-widest text-white/40 hover:text-white transition-all">
              Reset Canvas
            </button>
            {isBatchGenerating ? (
              <button onClick={handleStopBatch} className="h-10 px-8 rounded-xl bg-red-600 text-white text-[11px] font-black uppercase tracking-widest hover:bg-red-500 transition-all shadow-[0_0_20px_rgba(239,68,68,0.2)] flex items-center gap-2">
                <span className="material-symbols-outlined text-[18px]">stop_circle</span>
                Stop Batch
              </button>
            ) : (
              <button onClick={handleBatchGenerate} disabled={references.length === 0 || activeCount === 0} className="h-10 px-8 rounded-xl bg-white text-black text-[11px] font-black uppercase tracking-widest hover:bg-gray-200 transition-all disabled:opacity-30 shadow-[0_0_20px_rgba(255,255,255,0.1)]">
                Generate {activeCount} Slots
              </button>
            )}
          </div>
        </div>

        {/* Viewport Grid */}
        <div className="flex-1 p-6 overflow-hidden relative">
          <AnimatePresence mode="wait">
            <motion.div 
              key={activeTab}
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              exit={{ opacity: 0, y: -20 }}
              transition={{ duration: 0.3, ease: [0.16, 1, 0.3, 1] }}
              className={`grid h-full gap-4 ${activeTab === 'primary' ? 'grid-cols-3 grid-rows-3' : 'grid-cols-4 grid-rows-3'}`}
            >
              {gridSlots.map((slot) => (
                <EmotionCard 
                  key={slot.emotion} slot={slot} isBatchGenerating={isBatchGenerating}
                  onGenerate={() => generateSprite(slot.emotion)}
                  onImport={() => handleImportSprite(slot.emotion)}
                  onDownload={() => Flow.download({ base64: slot.base64!, mimeType: 'image/png', filename: `${getFilename(slot.emotion, slot.intensity)}.png` })} 
                  onIntensityChange={(v) => setSlots(prev => prev.map(s => s.emotion === slot.emotion ? { ...s, intensity: v, status: s.status === 'done' ? 'done' : 'idle' } : s))}
                  onZoom={() => slot.base64 && setPreviewSlot({ base64: slot.base64, label: getTierInfo(slot.emotion, slot.intensity).label, color: EMOTION_META[slot.emotion].color, emotion: slot.emotion })}
                  onToggleExclude={() => setSlots(prev => prev.map(s => s.emotion === slot.emotion ? { ...s, excluded: !s.excluded } : s))}
                />
              ))}
            </motion.div>
          </AnimatePresence>
        </div>

        {/* Export Footer */}
        <div className="h-20 shrink-0 flex items-center justify-center px-10 border-t border-white/5 bg-black/40 backdrop-blur-xl">
          {slots.some(s => s.status === 'done') ? (
            <button onClick={handleDownloadAll} disabled={downloadState !== 'idle'} className="flex items-center gap-3 px-10 h-11 rounded-2xl bg-white/10 hover:bg-white/15 border border-white/10 text-[11px] font-black uppercase tracking-widest text-white transition-all disabled:opacity-50">
              <span className="material-symbols-outlined text-[18px]">{downloadState === 'zipping' ? 'sync' : 'note_add'}</span>
              {downloadState === 'zipping' ? 'Packing ZIP...' : 'Export Sprite Pack'}
            </button>
          ) : (
            <span className="text-[10px] font-black text-white/20 uppercase tracking-[6px]">Generate emotes to unlock export</span>
          )}
        </div>
      </div>

      <AnimatePresence>
        {previewSlot && (
          <ZoomModal 
            image={previewSlot.base64} 
            label={previewSlot.label} 
            color={previewSlot.color} 
            onClose={() => setPreviewSlot(null)} 
            onRegenerate={() => {
              const emotion = previewSlot.emotion;
              setPreviewSlot(null);
              generateSprite(emotion);
            }}
          />
        )}
      </AnimatePresence>
    </div>
  );
}

const EmotionCard: React.FC<{
  slot: SpriteSlot; isBatchGenerating: boolean;
  onGenerate: () => void; onImport: () => void; onDownload: () => void;
  onIntensityChange: (v: Intensity) => void; onZoom: () => void;
  onToggleExclude: () => void;
}> = ({ slot, isBatchGenerating, onGenerate, onImport, onDownload, onIntensityChange, onZoom, onToggleExclude }) => {
  const meta = EMOTION_META[slot.emotion];
  const tier = getTierInfo(slot.emotion, slot.intensity);
  const isSpecial = slot.emotion.startsWith('SPECIAL');

  // Define if the slot should have an intensity slider
  const hasSlider = (!isSpecial && slot.emotion !== 'NEUTRAL') || slot.emotion === 'SPECIAL_1' || slot.emotion === 'SPECIAL_2';

  return (
    <div className={`flex flex-col bg-[#111] rounded-2xl border border-white/10 overflow-hidden relative group transition-all duration-300 ${slot.excluded ? 'opacity-20 grayscale scale-95' : 'opacity-100'}`}>
      {/* Header - Emotion Title Always Shown */}
      <div className="flex items-center justify-between p-3 shrink-0" style={{ background: `linear-gradient(to right, ${meta.color}90, transparent)` }}>
        <div className="flex items-center gap-2">
          <div className="w-6 h-6 rounded-lg flex items-center justify-center shadow-lg" style={{ background: '#000' }}>
            <span className="material-symbols-outlined text-[14px] font-bold" style={{ color: meta.color }}>{meta.icon}</span>
          </div>
          <div className="flex flex-col">
            <span className="text-[10px] font-black uppercase tracking-widest text-white [text-shadow:_0_1px_2px_rgb(0_0_0_/_60%)]">
              {meta.displayName}
            </span>
          </div>
        </div>
        <button onClick={onToggleExclude} className="w-5 h-5 rounded-lg border border-white/10 bg-black/40 flex items-center justify-center hover:bg-white/10 transition-all">
          <span className="material-symbols-outlined text-[12px] text-white/80">{slot.excluded ? 'visibility_off' : 'visibility'}</span>
        </button>
      </div>

      {/* Preview Area */}
      <div className="flex-1 flex items-center justify-center relative bg-black/40 overflow-hidden">
        {slot.status === 'idle' && (
          <div className="flex gap-6 items-center">
            <button onClick={onGenerate} disabled={isBatchGenerating} className="group/btn flex flex-col items-center gap-3 transition-all hover:scale-110 active:scale-95">
              <div className="w-12 h-12 rounded-full border border-white/10 flex items-center justify-center group-hover/btn:border-white/40 transition-all">
                <span className="material-symbols-outlined text-[24px] group-hover/btn:text-white" style={{ color: meta.color }}>auto_awesome</span>
              </div>
              <span className="text-[8px] font-black uppercase tracking-[3px] text-white/20 group-hover/btn:text-white">Generate</span>
            </button>
            <div className="h-12 w-px bg-white/5" />
            <button onClick={onImport} disabled={isBatchGenerating} className="group/btn flex flex-col items-center gap-3 transition-all hover:scale-110 active:scale-95">
              <div className="w-12 h-12 rounded-full border border-white/10 flex items-center justify-center group-hover/btn:border-white/40 transition-all">
                <span className="material-symbols-outlined text-[24px] text-white/20 group-hover/btn:text-white">upload_file</span>
              </div>
              <span className="text-[8px] font-black uppercase tracking-[3px] text-white/20 group-hover/btn:text-white">Import</span>
            </button>
          </div>
        )}
        {(slot.status === 'generating' || slot.status === 'processing') && (
          <div className="absolute inset-0 flex flex-col items-center justify-center gap-3 bg-black/60 loading-shimmer">
            <div className="w-8 h-8 border-2 border-white/10 border-t-white rounded-full animate-spin shadow-2xl" />
            <span className="text-[8px] font-black uppercase tracking-[4px] text-white animate-pulse">{slot.status === 'processing' ? 'Isolating...' : 'Crafting...'}</span>
          </div>
        )}
        {slot.status === 'done' && slot.base64 && (
          <div className="w-full h-full relative">
            <div className="absolute inset-0 pattern-checkered opacity-5" />
            <img 
              src={`data:image/png;base64,${slot.base64}`} 
              className="w-full h-full object-contain p-3 relative z-10 transition-transform group-hover:scale-105" 
              onClick={onZoom}
            />
            <div className="absolute inset-0 bg-white/0 hover:bg-white/5 transition-all cursor-zoom-in" onClick={onZoom} />

            {/* Quick Actions Overlay */}
            <div className="absolute bottom-2 right-2 flex gap-1 z-20 opacity-0 group-hover:opacity-100 transition-opacity">
               <button onClick={(e) => { e.stopPropagation(); onZoom(); }} className="w-8 h-8 rounded-lg bg-black/80 backdrop-blur-md flex items-center justify-center hover:bg-white hover:text-black transition-all" title="Inspect & Preview">
                <span className="material-symbols-outlined text-[16px]">zoom_in</span>
              </button>
               <button onClick={(e) => { e.stopPropagation(); onGenerate(); }} className="w-8 h-8 rounded-lg bg-black/80 backdrop-blur-md flex items-center justify-center hover:bg-white hover:text-black transition-all" title="Regenerate">
                <span className="material-symbols-outlined text-[16px]">refresh</span>
              </button>
               <button onClick={(e) => { e.stopPropagation(); onImport(); }} className="w-8 h-8 rounded-lg bg-black/80 backdrop-blur-md flex items-center justify-center hover:bg-white hover:text-black transition-all" title="Replace Image">
                <span className="material-symbols-outlined text-[16px]">sync</span>
              </button>
               <button onClick={(e) => { e.stopPropagation(); onDownload(); }} className="w-8 h-8 rounded-lg bg-black/80 backdrop-blur-md flex items-center justify-center hover:bg-white hover:text-black transition-all" title="Download PNG">
                <span className="material-symbols-outlined text-[16px]">download</span>
              </button>
            </div>
          </div>
        )}
        {slot.status === 'error' && (
           <div className="flex flex-col items-center gap-2 text-red-500">
            <span className="material-symbols-outlined text-[32px]">error</span>
            <span className="text-[8px] font-black uppercase">{slot.error || 'Failed'}</span>
            <div className="flex gap-2">
              <button onClick={onGenerate} className="text-[8px] underline">Retry</button>
              <button onClick={onImport} className="text-[8px] underline">Import</button>
            </div>
          </div>
        )}
      </div>

      {/* Controls */}
      <div className="p-3 bg-black/60 shrink-0 border-t border-white/5">
        {hasSlider ? (
           <div className="flex flex-col gap-1">
             <div className="flex justify-between items-center text-[7px] font-black text-white/30 uppercase">
               <span>Intensity</span>
               <span style={{ color: meta.color }}>{tier.label}</span>
             </div>
             <input 
                type="range" 
                min="1" 
                max={isSpecial ? 3 : (slot.emotion === 'JOY' || slot.emotion === 'FEAR' || slot.emotion === 'SADNESS' || slot.emotion === 'ANGER' ? 12 : 8)} 
                step="1" 
                value={slot.intensity as number} 
                onChange={(e) => onIntensityChange(parseInt(e.target.value))} 
                disabled={isBatchGenerating}
                style={{ '--thumb-color': meta.color } as any}
             />
           </div>
        ) : (
          <div className="flex flex-col gap-0.5 items-center justify-center h-7">
            <span className="text-[7px] font-black text-white/20 uppercase tracking-[4px]">
              {tier.label}
            </span>
          </div>
        )}
      </div>
    </div>
  );
};

